class MockTornAPIWrapper(TornAPIWrapper):
    def __init__(
        self,
        api_key: str = 'mock-api-key',
        request_timeout: float | tuple[float, float] = 10,
        *,
        controller: MockController | None = None,
    ) -> None:
        # Deliberately do not call TornAPIWrapper.__init__.
        # That prevents creation of requests/aiohttp sessions.
        self.api_key = api_key
        self.request_timeout = request_timeout
        self._mock = controller or MockController()
        self.company = SyncCompany(self)
        self.faction = SyncFaction(self)
        self.forum = SyncForum(self)
        self.key = SyncKey(self)
        self.market = SyncMarket(self)
        self.property = SyncProperty(self)
        self.racing = SyncRacing(self)
        self.torn = SyncTorn(self)
        self.user = SyncUser(self)

    @property
    def calls(self) -> list[MockRequest]:
        return self._mock.calls

    def set_response(
        self,
        endpoint: str,
        response: ResponseOverride,
    ) -> None:
        self._mock.set_response(endpoint, response)

    def set_error(
        self,
        endpoint: str,
        error: BaseException | type[BaseException],
    ) -> None:
        self._mock.set_error(endpoint, error)

    def reset(self) -> None:
        self._mock.reset()

    def request(
        self,
        endpoint: str,
        params: dict | None,
    ) -> dict | str:
        return self._mock.request(endpoint, params)

class MockTornAPIWrapperAsync(TornAPIWrapperAsync):
    def __init__(
        self,
        api_key: str = 'mock-api-key',
        request_timeout: float | tuple[float, float] = 10,
        *,
        controller: MockController | None = None,
    ) -> None:
        # Deliberately do not call TornAPIWrapper.__init__.
        # That prevents creation of requests/aiohttp sessions.
        self.api_key = api_key
        self.request_timeout = request_timeout
        self._mock = controller or MockController()
        self.company = AsyncCompany(self)
        self.faction = AsyncFaction(self)
        self.forum = AsyncForum(self)
        self.key = AsyncKey(self)
        self.market = AsyncMarket(self)
        self.property = AsyncProperty(self)
        self.racing = AsyncRacing(self)
        self.torn = AsyncTorn(self)
        self.user = AsyncUser(self)

    @property
    def calls(self) -> list[MockRequest]:
        return self._mock.calls

    def set_response(
        self,
        endpoint: str,
        response: ResponseOverride,
    ) -> None:
        self._mock.set_response(endpoint, response)

    def set_error(
        self,
        endpoint: str,
        error: BaseException | type[BaseException],
    ) -> None:
        self._mock.set_error(endpoint, error)

    def reset(self) -> None:
        self._mock.reset()

    async def request(
        self,
        endpoint: str,
        params: dict | None,
    ) -> dict | str:
        return self._mock.request(endpoint, params)

    async def close(self) -> None:
        return None

    async def __aenter__(self) -> MockTornAPIWrapperAsync:
        return self

    async def __aexit__(self, exc_type, exc, tb) -> None:
        await self.close()

